class Solution {
public:
    int maxPalindromes(std::string s, int k) {
        int n = s.length();
        int ans = 0;
        int last_end = 0;
        auto is_pal = [&](int l, int r) {
            while (l < r) {
                if (s[l++] != s[r--]) return false;
            }
            return true;
        };
        for (int i = 0; i < n; ++i) {
            if (i - k + 1 >= last_end && is_pal(i - k + 1, i)) {
                ans++;
                last_end = i + 1;
            } else if (i - k >= last_end && is_pal(i - k, i)) {
                ans++;
                last_end = i + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int maxPalindromes(String s, int k) {
        int n = s.length();
        int ans = 0;
        int lastEnd = 0;
        for (int i = 0; i < n; i++) {
            if (i - k + 1 >= lastEnd && isPal(s, i - k + 1, i)) {
                ans++;
                lastEnd = i + 1;
            } else if (i - k >= lastEnd && isPal(s, i - k, i)) {
                ans++;
                lastEnd = i + 1;
            }
        }
        return ans;
    }
    private boolean isPal(String s, int l, int r) {
        while (l < r) {
            if (s.charAt(l++) != s.charAt(r--)) return false;
        }
        return true;
    }
}

